                           errors="replace", env=env, timeout=timeout, cwd=ROOT)
    except (OSError, subprocess.TimeoutExpired) as exc:
        return 1, "", f"{type(exc).__name__}: {exc}"
    return p.returncode, p.stdout, p.stderr


def _env() -> dict:
    sys.path.insert(0, str(ROOT / "src"))
    try:
